[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path
if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$relative=$PacketPath.Replace('\','/').Trim();if($relative.Contains('..')-or $relative -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'}
$full=Join-Path $root ($relative.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "GameCore packet missing: $relative"};$outputRoot=(Resolve-Path (Join-Path $root 'ES\Output')).Path.TrimEnd('\','/');$resolved=(Resolve-Path $full).Path;if(-not $resolved.StartsWith("$outputRoot$([IO.Path]::DirectorySeparatorChar)",[StringComparison]::OrdinalIgnoreCase)){throw 'Resolved packet path escapes ES/Output.'}
$raw=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes($resolved));if($raw -match '(?i)"(?:parallelSingleton|reflectionDiscovery|editorScan)"\s*:\s*(?:true|"true")'){throw 'GameCore packet uses a forbidden parallel or implicit registration path.'};$p=$raw|ConvertFrom-Json
foreach($x in @('schemaVersion','rootAuthority','ownershipCategory','injection','reinjection','transaction','rollback','consumer','stableIdentity','evidenceRef','owner','staleWhen')){if($null -eq $p.PSObject.Properties[$x]){throw "Missing GameCore field: $x"}}
if([string]$p.schemaVersion -ne '1'-or [string]$p.reinjection -ne 'same-instance'){throw 'GameCore packet requires schemaVersion 1 and same-instance reinjection.'};if([string]$p.stableIdentity -match '(?i)runtime(key|id)'){throw 'RuntimeKey/RuntimeId cannot be a persistent GameCore identity.'};Write-Output "PASS: GameCore ownership, explicit injection, same-instance reinjection and rollback are declared: $relative"
